// Story mode copy, part one "Unheard Echoes" (OWNER_APPROVED_ADAPTATION
// 2026-11-11), in the five product locales. Scoped dictionary registered with
// scripts/check-locale-coverage.mjs. {tamer} and {partner} are filled at play
// time and never translated; {n} and {name} are filled by the theater.

const freezeDeep = value => {
  if (value && typeof value === "object") { for (const item of Object.values(value)) freezeDeep(item); return Object.freeze(value); }
  return value;
};

export const STORY_VN_LOCALES = Object.freeze(["zh-Hant","en","ja","th","vi"]);

