    "V1_NAVI_INVITE": "{tamer}, registration for the local cup closes today. The warp gate is already open for you!",
    "V1_N_AVATAR": "In the Data Area, tamers appear through their partners. The voice you hear is a person's; the figure you see is the partner beside them.",
    "V1_N_HEAVY": "Heavy footsteps thud across the paving. The crowd in the plaza parts on its own.",
    "V1_P_SEARCH": "Just a sec! I've almost found it!",
    "V2_NAVI_TRUCE": "Both factions just sent you an invitation to their investigation team... {tamer}, that doesn't happen often.",
    "V3_NAVI_DIVE": "Diving to layer seven. {tamer}, the signal is messy down here — keep {partner} where you can see it.",
    "V4_NAVI_SEAL": "The two locks have completely different waveforms. Looks like both sides have to turn their keys together.",
    "V5_NAVI_ALERT": "Every channel has been seized! {tamer}, the name fields on every terminal are... going blank, all at once!",
    "V6_LOSE": "Hold on! Even if that one got through, the route is still here — we push it back together!",
    "V6_NAVI_ALL": "All three routes are open at once. {tamer}, this time everyone is on the same channel.",
    "V6_RESONANCE": "{partner} begins to glow — the light you two gathered on the whole way here.",
