    "V1_NAVI_INVITE": "{tamer}、地方大会のエントリーは今日まで！ ワープゲートはもう開いてるよ！",
    "V1_N_AVATAR": "Data Area では、テイマーはパートナーの姿を通して現れる。聞こえるのは人の声、見えるのはそばにいるパートナー。",
    "V1_N_HEAVY": "重い足音が石畳を踏み鳴らす。広場の人だかりが、ひとりでに道を開けた。",
    "V1_P_SEARCH": "ちょっと待って！もうすぐ見つかるから！",
    "V2_NAVI_TRUCE": "両陣営から同時に調査隊への招待が届いたよ……{tamer}、こんなことめったにないんだから。",
