    "C1_N2": "ช่วงที่เธอออฟไลน์ มันก็ยังใช้ชีวิตเล็ก ๆ ของมันในถิ่นที่อยู่ตามปกติ",
    "C1_N_END": "ผลแพ้ชนะบอกได้แค่นัดนั้น ไม่ใช่ความผูกพัน ชื่อบนใบสมัครยังคงเปล่งแสง",
    "C1_P_DOOR": "เร็วเข้า เร็วเข้า! จุดสมัครแข่งอยู่อีกฝั่งของประตูวาร์ป!",
    "C1_P_GIFT": "ให้เธอ! ก้อนหินเรืองแสงที่เจอในถิ่นที่อยู่วันนี้",
    "C1_P_LOSE": "ไม่เป็นไร! ที่แพ้คือนัดนี้ ไม่ใช่พวกเรา",
