    "P3C6_GATE": "พอมองเห็นตัวอักษรรางๆ: \"ยินดีต้อนรับก...\" ที่เหลือถูกลมพัดหายไป",
    "P3C6_GOAL": "หาร่องรอยของไอจังในฟาร์ม ({n}/{total})",
