    "P3C6_L_GATE": "ป้ายไม้ที่ประตู",
    "P3C6_N1": "ใต้ฟ้าเต็มดาว ฟาร์มเล็กๆ ลอยอยู่ในความว่างเปล่า ป้ายไม้ที่ประตูอ่านไม่ออกแล้ว",
    "P3C6_N2": "ตั้งแต่วันนั้น บนเคาน์เตอร์ห้องโถงสมาคม มีใบสมัครที่เขียนชื่อไอจังติดอยู่",
    "P3C6_P1": "ตอนนี้มีแล้ว! พวกเรามาแล้ว!",
    "P3C6_P2": "เสียงของเธอ ทุกคนได้ยินกันหมดแล้ว!",
    "P3C6_P3": "ยินดีต้อนรับกลับนะ ไอจัง!",
