    "P3C6_R1": "มีคนตอบแล้ว ข้อมูลของแกหมดอายุแล้ว ผู้รีไซเคิล",
    "P3C6_S1": "ไอจังพูด \"ยินดีต้อนรับกลับ\" กับพวกเรามาเป็นพันๆ ครั้ง! ครั้งนี้ถึงตาพวกเราตอบ!",
    "P3C6_SUMMARY": "ฟาร์มที่ถูกลืม เด็กที่รอมานานแสนนาน กำลังจะเขียนชื่อของตัวเองในที่สุด",
    "P3C6_TITLE": "ยินดีต้อนรับกลับ",
