    "P3H_GOAL": "แตะพื้นเพื่อเดิน · ไปหาไอจังที่เคาน์เตอร์เพื่อรับคำขอ",
    "P3H_O1": "ฉันจัดเอกสารเรียบร้อยแล้ว พอไอจังอยู่ ห้องโถงก็คึกคักเสมอเลย",
    "P3H_SUMMARY": "ห้องโถงใหม่ที่ไอจังประจำเคาน์เตอร์ คุยกับเธอเพื่อรับบทเนื้อเรื่องและคำขอ",
    "P3H_TITLE": "สมาคมคู่หู · ห้องโถงต้อนรับ",
    "P3R1_AGAIN": "ตรงนี้ดูแล้ว",
    "P3R1_B1": "หมอนงีบของฉันปลิวไปกับลม... ไม่มีมันฉันนอนไม่หลับ...",
    "P3R1_B2": "เจอแล้ว! ขอบคุณนะ! วันนี้ต้องงีบหลับสบายแน่ๆ!",
