    "P3R1_F2": "มีเส้นไหมพรมห้อยอยู่ที่ป้าย... มาจากหมอนแน่! ลมพัดไปทางต้นไม้ใหญ่",
    "P3R1_F3": "ในรังใต้ต้นไม้ใหญ่ หมอนงีบนอนอยู่อย่างปลอดภัย อุ่นจากแสงแดด",
    "P3R1_GOAL": "หาหมอนงีบในถิ่นอาศัย",
