    "P3R1_SUMMARY": "หมอนงีบของครืดคราดปลิวไปกับลม ไปหาที่ถิ่นอาศัยของคู่หูกัน",
    "P3R1_TITLE": "หมอนงีบของครืดคราด",
    "P3R2_ECHO": "ทุกชื่อต้องมีเครื่องหมายยืนยันว่าได้รับแล้ว",
    "P3R2_F1": "ในแปลงดอกไม้มีแต่ผีเสื้อ",
    "P3R2_F2": "หลังจอของโต๊ะรับสมัคร ตราประทับติดอยู่ในช่อง ยังเปล่งประกาย",
    "P3R2_GOAL": "หาตราประทับของโอรัน",
    "P3R2_K1": "ตราประทับเหรอ? เมื่อกี้เห็นอะไรเรืองแสงอยู่หลังโต๊ะรับสมัคร!",
    "P3R2_L1": "แปลงดอกไม้",
    "P3R2_L2": "โต๊ะรับสมัคร",
    "P3R2_LOCK": "ที่โต๊ะคนเยอะมาก ถามก่อนดีกว่าว่ามีใครเห็นไหม",
    "P3R2_O1": "แย่แล้ว ตราประทับหายไป! ไม่มีมัน วันนี้รับสมัครไม่ได้เลย...",
    "P3R2_O2": "นั่นแหละ! ขอบคุณมากๆ ขอประทับตราพิเศษให้นะ",
    "P3R2_SUMMARY": "โอรันทำตราประทับสมัครหาย มีคนเห็นของวิบวับที่ลานการแข่งขัน",
    "P3R2_TITLE": "ตราประทับของเจ้าหน้าที่",
    "P3R3_ECHO": "มีแต่จดหมายที่ส่งถึง ถึงจะกลายเป็นเสียงสะท้อน",
    "P3R3_F1": "บนป้ายติดโปสเตอร์ศึกภูมิภาค คู่หูของสุบารุยืนอยู่ตรงกลาง เท่มาก",
    "P3R3_GOAL": "เอาจดหมายไปให้สุบารุ",
    "P3R3_K1": "ช่วยเอาจดหมายนี้ไปให้พี่สุบารุได้ไหม? ฉันตื่นเต้นจนไม่กล้าเอาไปเอง...",
    "P3R3_L1": "ป้ายโฆษณาใหญ่",
    "P3R3_N1": "ระหว่างทางกลับ เหมือนได้ยินใครแอบส่งเสียงเชียร์อยู่ไกลๆ",
    "P3R3_P1": "ปล่อยให้เป็นหน้าที่เรา!",
    "P3R3_S1": "จดหมายถึงฉัน? ดาวน้อยเขียนเหรอ?",
    "P3R3_S2": "\"ฉันก็อยากเปล่งประกายแบบพี่\"... จริงๆ เลย แบบนี้ฉันต้องพยายามมากขึ้นอีกแล้ว",
    "P3R3_SUMMARY": "ผู้ฝึกหัดดาวน้อยเขียนจดหมายถึงสุบารุ ช่วยนำไปส่งที่นครอารีนาลอยฟ้า",
    "P3R3_TITLE": "จดหมายของดาวน้อย",
    "P3R4_ECHO": "คู่แข่ง คือหนึ่งในคนที่เข้าใจเธอที่สุด",
    "P3R4_P1": "รินก็อยากหาคนซ้อมด้วยเหรอ?",
    "P3R4_P2": "มาหาพวกเราได้ทุกเมื่อเลยนะ!",
    "P3R4_R1": "มาแล้วเหรอ ช่วงนี้ทุกคนยุ่งกับคำขอ สนามเลยว่างโล่ง",
    "P3R4_R2": "...ไม่ต้องพูดมาก จะสู้ก็สู้",
    "P3R4_R3": "...ขอบใจ ช่วงนี้หัวยุ่งไปหมด สู้สักรอบแล้วดีขึ้นเยอะ",
    "P3R4_R_LOSE": "อีกนิดเดียว คู่หูของเธอเก่งกว่าที่เธอคิดนะ",
    "P3R4_R_WIN": "ฮึ เก่งขึ้นอีกแล้ว ครั้งหน้าฉันชนะแน่",
    "P3R4_SUMMARY": "รินอยากซ้อม ในสนามที่ไม่มีใคร มีแค่พวกเธอสองคน",
    "P3R4_TITLE": "การซ้อมกลางคืนของริน",
    "P3R5_ECHO": "ขาดเฟืองไปอันเดียว นาฬิกาทั้งเรือนก็หยุดเดิน",
