    "P3R5_F2": "ใต้เสาไฟ มีเฟืองขนาดกลางกลิ้งอยู่",
    "P3R5_F3": "หลังลังไม้หน้าร้าน มีเฟืองใหญ่ติดอยู่",
    "P3R5_GOAL": "เก็บเฟือง ({n}/{total})",
    "P3R5_L": "ของที่เป็นประกาย",
    "P3R5_LOCK": "ยังเก็บเฟืองไม่ครบนะ",
    "P3R5_M1": "กำลังซ่อมนาฬิกาใหญ่ของห้องโถง แต่เฟืองดันกลิ้งไปทั่ว ช่วยเก็บมาให้สามอันที",
    "P3R5_M2": "ครบแล้ว! นาฬิกาของห้องโถงจะเดินได้อีกครั้งพรุ่งนี้",
    "P3R5_M3": "ไอจังบอกเสมอว่าอยากได้ยินเสียงนาฬิกาใหญ่ เธอต้องดีใจแน่",
    "P3R5_SUMMARY": "ร้านซ่อมของบาร์ดขาดเฟืองไปสามอัน ดูเหมือนกระจายอยู่ทั่วถนนช่าง",
    "P3R5_TITLE": "เฟืองของร้านซ่อม",
    "P3R6_C1": "ยินดีต้อนรับ ไฟในเขตพักฟื้นมีไว้สำหรับคนที่กลับดึก",
    "P3R6_C2": "แต่เมื่อคืนดับไปสามดวง ...หลังจากผู้รีไซเคิลผ่านไปไม่นาน",
