    "P5C1_N2": "ตอนที่จากซากเมืองไป ตัวอักษรบนอนุสาวรีย์ดูเหมือนจะเรืองแสงขึ้นเล็กน้อย",
    "P5C1_NOTICE": "ประกาศยุติการให้บริการ",
    "P5C1_NOTICE_BODY": "ขอบคุณที่อยู่ด้วยกันมาตลอด\nโลกนี้จะหยุดให้บริการในเวลาเที่ยงคืน\nเมื่อเซิร์ฟเวอร์ปิดลง ข้อมูลทั้งหมดในโลกจะไม่สามารถเข้าถึงได้อีก\n—— ทีมงานโลกแรก",
