    "P5C2_G3": "รอยแยกนี้ไม่ได้ถูกเปิดจากคนข้างนอก แต่ถูกฉีกจากข้างใน——ด้วยเสียงหนึ่งที่ไม่ยอมแพ้",
    "P5C2_GOAL": "สำรวจทะเลเยือกแข็ง ({n}/{total})",
