    "P5C3_P_STOP": "มันกำลังทำร้ายทุกคน ต้องหยุดมันก่อน แล้วค่อย... ฟังมันพูดให้ดี",
    "P5C3_SUMMARY": "หอสมุดแห่งโลกที่ถูกปิด ที่นี่ เธอได้รู้เรื่องของ \"ซีโร่\"",
    "P5C3_TITLE": "โลกที่ถูกปิด",
