    "P5C4_S1": "พวกเจ้ามาแล้ว บนอัฒจันทร์การแข่ง บนเวทีระดับชาติ ที่ฟาร์มที่ถูกลืม... ข้าเฝ้ามองพวกเจ้ามาตลอด",
    "P5C4_S2": "โลกนี้เต็มไปด้วยเสียงที่ไม่มีใครตอบ ข้าจึงคิดว่า ถ้าทุกเสียงกลายเป็นหนึ่งเดียว——",
    "P5C4_S3": "ก็จะไม่มีใครต้องรออยู่ที่ประตูจนโลกสิ้นสุดอีก",
