    "SPEAKER_HOST": "ชาร์ล็อต · ผู้บรรยาย",
    "SPEAKER_HUSH": "ฮัช · บัวดำหัวรุนแรง",
    "SPEAKER_MECHANIC": "บาร์ด · ร้านซ่อม",
    "SPEAKER_NAVI": "ผู้นำทางการแข่งขัน NAVI",
