    "SPEAKER_REGISTRAR": "โอรัน · เจ้าหน้าที่รับสมัคร",
    "SPEAKER_REPORTER": "นักข่าวการแข่งขัน · สตาร์คอป",
    "SPEAKER_RESIDENT": "โนโซมิ · ผู้พักฟื้น",
    "SPEAKER_RIVAL": "ริน · เหล็กดำ",
    "SPEAKER_SCRIPT": "ราชาแห่งบท",
