    "V1_NAVI_INVITE": "{tamer} การลงทะเบียนศึกท้องถิ่นปิดวันนี้นะ ประตูวาร์ปเปิดรอพวกเธอแล้ว!",
    "V1_N_AVATAR": "ใน Data Area เทมเมอร์ปรากฏตัวผ่านร่างของคู่หู — เสียงที่ได้ยินคือเสียงของคน ส่วนร่างที่เห็นคือคู่หูที่อยู่ข้างพวกเขา",
    "V1_N_HEAVY": "เสียงฝีเท้าหนักกระทบพื้นหิน ผู้คนในลานต่างหลีกทางให้เอง",
    "V1_P_SEARCH": "แป๊บเดียว! ใกล้เจอแล้ว!",
    "V2_NAVI_TRUCE": "ทั้งสองฝ่ายส่งคำเชิญเข้าทีมสืบสวนมาให้เธอพร้อมกัน... {tamer} เรื่องแบบนี้ไม่ได้เกิดบ่อยนะ",
    "V3_NAVI_DIVE": "ดำลงสู่ชั้นที่เจ็ด {tamer} สัญญาณที่นี่ยุ่งเหยิงมาก ให้ {partner} อยู่ในที่ที่เธอมองเห็นนะ",
    "V4_NAVI_SEAL": "คลื่นของกุญแจสองดอกต่างกันโดยสิ้นเชิง ดูเหมือนทั้งสองฝ่ายต้องหมุนกุญแจพร้อมกัน",
    "V5_NAVI_ALERT": "ช่องสัญญาณทั้งเขตถูกยึด! {tamer} ช่องชื่อในทุกเทอร์มินัล... กำลังว่างเปล่าพร้อมกันหมด!",
    "V6_LOSE": "อดทนไว้! ถึงครั้งนี้จะกันไม่อยู่ เส้นทางก็ยังอยู่ — เราจะดันมันกลับไปด้วยกัน!",
    "V6_NAVI_ALL": "ทั้งสามเส้นทางเปิดพร้อมกัน {tamer} ครั้งนี้ทุกคนอยู่ในช่องสัญญาณเดียวกัน",
    "V6_RESONANCE": "ร่างของ {partner} เริ่มเปล่งแสง — แสงที่พวกเธอสะสมมาด้วยกันตลอดทางจนถึงที่นี่",
    "VN_AUTO": "อัตโนมัติ",
